import * as THREE from 'three';
import Stats from 'stats.js';

import { ThreeCore } from '..';

export class RendererWrapper {
	public core: ThreeCore;
	public scene: THREE.Scene;
	public renderer: THREE.WebGLRenderer;

	public requestFrame: number;

	public t: number = 0.0;
	public deltaTime: number = 0.0;

	private _stats: Stats;
	private _initPost = true;
	private _clock: THREE.Clock = undefined;

	constructor(threeCore: ThreeCore) {
		this.core = threeCore;
		THREE.Object3D.DEFAULT_UP.set(this.core.upVector.x, this.core.upVector.y, this.core.upVector.z);
		this.init();
		this.initBinding();
	}
	public init() {
		this.scene = new THREE.Scene();
		this.scene.background = new THREE.Color(0, 0, 0);
		this.scene.castShadow = true;

		this.renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, powerPreference: 'high-performance' });
		this.renderer.setPixelRatio(this.core.host.clientWidth / this.core.host.clientHeight);
		this.renderer.domElement.id = 'hypercube-renderer';

		this.renderer.shadowMap.enabled = true;
		this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
		this.renderer.toneMapping = THREE.ACESFilmicToneMapping;

		this.renderer.toneMappingExposure = 1.5;
		this.renderer.outputColorSpace = THREE.SRGBColorSpace;
		this.renderer.localClippingEnabled = true;

		this.renderer.setSize(this.core.host.clientWidth, this.core.host.clientHeight);
		this.core.host.appendChild(this.renderer.domElement);

		this.scene.background = new THREE.Color(0xffffff);
		// this.scene.background = new THREE.Color(0x000000);
	}
	public initBinding() {
		this.core.scene = this.scene;
		this.core.renderer = this.renderer;
	}
	public start() {
		this.removeLoading();

		this._stats = new Stats();
		this._stats.showPanel(0); // 0: FPS, 1: ms, 2: memory
		this._stats.dom.style.position = 'absolute';
		this._stats.dom.style.top = '0px';
		this._stats.dom.style.right = '0px';
		this._stats.dom.style.left = '';
		this.core.host.appendChild(this._stats.dom);

		this._clock = new THREE.Clock();
		this._initPost = false;

		this.core.initUI();
	}
	public loop = () => {
		this.requestFrame = requestAnimationFrame(this.loop);
		if (this.core.readyBinding() && this.core.ready) {
			if (this._initPost) {
				this.start();
			}

			// console.log('deltaTime:', this.deltaTime);
			this._stats.begin();
			// console.log('rendering...');
			this.core.cameraWrapper.update();
			this.core.update();

			// if (this.postProcessingWrapper.needPostProcessing) {
			// this.groundReflector.visible = false; // 자기 자신 반사 제외
			// this.renderer.setRenderTarget(this.postProcessingWrapper.reflectorRT);
			// this.renderer.render(this.scene, this.cameraWrapper.camera);
			// this.groundReflector.visible = true;

			// this.postProcessingWrapper.blurComposer.render();

			// this.groundReflector.material.uniforms.tDiffuse.value = this.postProcessingWrapper.blurredReflectionRT.texture;
			// console.log(this.groundReflector.material.uniforms.tDiffuse.value);

			this.core.postProcessingWrapper.render();
			// } else {
			// 	this.renderer.render(this.scene, this.cameraWrapper.camera);
			// }

			this.t += 0.01;
			this.deltaTime = this._clock.getDelta();
			this._stats.end();
		}
	};
	private removeLoading() {
		const loadingDiv = document.getElementById('loading');
		if (loadingDiv && loadingDiv.parentElement) {
			loadingDiv.parentElement.removeChild(loadingDiv);
		}
	}
}
